head.script:

scwin.onpageload = function() {
	requires("uiplugin.popup");	
	var parent = $p.parent().text1.getValue();	
	var triggerName = parent;
	trigger1.setLabel(triggerName + " - pageFrame - (options.frameModal : top)");
	text1.hide();


	var parent2 = $p.parent().text2.getValue();	
	var triggerName2 = parent2;
	trigger2.setLabel(triggerName2 + " - wframe - (options.frameModal : frame)");
	text2.hide();

};

scwin.onpageunload = function() {

};


scwin.trigger1_onclick = function(e) {	
	var options = {  		 
	        id : "pageFramePopup - top", 
	        type : "pageFramePopup", // "iframePopup", "browserPopup"
	        width: "300px", 
	        height: "200px", 
	        popupName :"pageFramePopup - top",       
	        modal : "true",		     
	        frameModal : "top"
	    }; 

    $p.openPopup("",  options );
};

scwin.trigger2_onclick = function(e) {
	var options = {  		 
	        id : "wframePopup - frame", 
	        type : "wframePopup", // "iframePopup", "browserPopup"
	        width: "300px", 
	        height: "200px", 
	        popupName :"wframePopup - frame",	  
	        resizable: true,	             
	        modal : "true",		     
	        frameModal : "frame"
	    }; 

    $p.openPopup("",  options );

};

scwin.trigger3_onclick = function(e) {
	var options = {  		 
	        id : "iframePopup - frame", 
	        type : "iframePopup", // "iframePopup", "browserPopup"
	        width: "300px", 
	        height: "200px", 
	        top: "200", 
	        left: "200", 
	        popupName : "iframePopup - frame",	
	        resizable: true,	            
	        modal : "true",		     
	        frameModal : "frame" 
	    }; 

    $p.openPopup("",  options );
};
